def _get_test_files() -> List[Path]:
    """Return all test files in the test root."""
    return sorted(TEST_ROOT.glob("test_*.py"))


def _get_test_functions(file_path: Path) -> List[str]:
    """Extract test function names from a test file."""
    content = file_path.read_text(encoding="utf-8")
    functions = []
    for line in content.splitlines():
        stripped = line.strip()
        if stripped.startswith("def test_") and "(" in stripped:
            func_name = stripped[4:].split("(")[0].strip()
            functions.append(func_name)
    return functions


def _get_fixture_names(file_path: Path) -> List[str]:
    """Extract fixture names from a test file."""
    content = file_path.read_text(encoding="utf-8")
    fixtures = []
    for line in content.splitlines():
        stripped = line.strip()
        if stripped.startswith("@pytest.fixture"):
            # Look ahead for the function definition
            continue
        if "def " in stripped and "fixture" in stripped.lower():
            # Heuristic: fixture functions often have 'fixture' in name
            pass
        # More robust: look for @pytest.fixture decorator
    # Parse with AST for accuracy
    import ast
    try:
        tree = ast.parse(content)
        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef):
                for decorator in node.decorator_list:
                    if isinstance(decorator, ast.Call) and isinstance(decorator.func, ast.Attribute):
                        if decorator.func.attr == "fixture":
                            fixtures.append(node.name)
                    elif isinstance(decorator, ast.Name) and decorator.id == "fixture":
                        fixtures.append(node.name)
    except SyntaxError:
        pass
    return fixtures


def _get_markers_from_file(file_path: Path) -> Set[str]:
    """Extract pytest markers used in a test file."""
    content = file_path.read_text(encoding="utf-8")
    markers = set()
    import re
    marker_pattern = re.compile(r"@pytest\.mark\.(\w+)")
    markers.update(marker_pattern.findall(content))
    return markers


def _validate_pytest_ini() -> Dict[str, Any]:
    """Validate pytest.ini or pyproject.toml configuration."""
    result = {
        "exists": False,
        "path": None,
        "markers": [],
        "testpaths": [],
        "valid": False,
        "errors": []
    }

    # Check for pytest.ini
    pytest_ini = PROJECT_ROOT / "pytest.ini"
    if pytest_ini.exists():
        result["exists"] = True
        result["path"] = str(pytest_ini)
        content = pytest_ini.read_text(encoding="utf-8")
        if "[pytest]" not in content:
            result["errors"].append("Missing [pytest] section")
        else:
            # Parse markers
            import configparser
            config = configparser.ConfigParser()
            config.read(pytest_ini)
            if "pytest" in config:
                if "markers" in config["pytest"]:
                    markers = config["pytest"]["markers"].splitlines()
                    result["markers"] = [m.split(":")[0].strip() for m in markers if m.strip()]
                if "testpaths" in config["pytest"]:
                    result["testpaths"] = config["pytest"]["testpaths"].split()
            result["valid"] = not result["errors"]

    # Check pyproject.toml
    pyproject = PROJECT_ROOT / "pyproject.toml"
    if pyproject.exists() and not result["exists"]:
        result["exists"] = True
        result["path"] = str(pyproject)
        content = pyproject.read_text(encoding="utf-8")
        if "[tool.pytest.ini_options]" not in content:
            result["errors"].append("Missing [tool.pytest.ini_options] section")
        else:
            # Basic TOML parsing
            import tomllib
            try:
                with open(pyproject, "rb") as f:
                    data = tomllib.load(f)
                pytest_config = data.get("tool", {}).get("pytest", {}).get("ini_options", {})
                result["markers"] = list(pytest_config.get("markers", {}).keys())
                result["testpaths"] = pytest_config.get("testpaths", [])
                result["valid"] = True
            except Exception as e:
                result["errors"].append(f"TOML parse error: {e}")

    return result


def _validate_conftest() -> Dict[str, Any]:
    """Validate conftest.py existence and content."""
    result = {
        "exists": False,
        "path": None,
        "fixtures": [],
        "hooks": [],
        "valid": False,
        "errors": []
    }

    conftest = TEST_ROOT / "conftest.py"
    if not conftest.exists():
        conftest = PROJECT_ROOT / "conftest.py"

    if conftest.exists():
        result["exists"] = True
        result["path"] = str(conftest)
        content = conftest.read_text(encoding="utf-8")

        # Check for fixtures
        result["fixtures"] = _get_fixture_names(conftest)

        # Check for hooks
        import re
        hook_pattern = re.compile(r"def pytest_(\w+)")
        result["hooks"] = hook_pattern.findall(content)

        # Validate syntax
        try:
            compile(content, str(conftest), "exec")
            result["valid"] = True
        except SyntaxError as e:
            result["errors"].append(f"Syntax error: {e}")

    return result


