class TestFixtureValidation:
    """Validate fixture availability and correctness."""

    def test_builtin_fixtures_available(self):
        """Built-in pytest fixtures must be available."""
        test_files = _get_test_files()

        for test_file in test_files:
            content = test_file.read_text(encoding="utf-8")
            for fixture in REQUIRED_FIXTURES:
                # Check if fixture is used in the file
                if fixture in content:
                    # Verify it's used as a parameter
                    assert f"({fixture}" in content or f", {fixture}" in content, (
                        f"Fixture {fixture} referenced but not used as parameter in {test_file.name}"
                    )

    def test_custom_fixtures_defined_in_conftest(self):
        """Custom fixtures must be defined in conftest.py."""
        conftest = TEST_ROOT / "conftest.py"
        if not conftest.exists():
            conftest = PROJECT_ROOT / "conftest.py"

        if conftest.exists():
            content = conftest.read_text(encoding="utf-8")
            assert "@pytest.fixture" in content, (
                "conftest.py must define at least one fixture"
            )

    def test_fixture_scopes_are_valid(self):
        """Fixture scopes must be one of: function, class, module, package, session."""
        valid_scopes = {"function", "class", "module", "package", "session"}
        test_files = _get_test_files()
        conftest = TEST_ROOT / "conftest.py"
        if conftest.exists():
            test_files.append(conftest)

        for test_file in test_files:
            content = test_file.read_text(encoding="utf-8")
            import re
            scope_pattern = re.compile(r"scope\s*=\s*['\"]([^'\"]+)['\"]")
            for match in scope_pattern.finditer(content):
                scope = match.group(1)
                assert scope in valid_scopes, (
                    f"Invalid fixture scope '{scope}' in {test_file.name}"
                )

    def test_fixture_dependencies_are_resolvable(self):
        """Fixture dependencies must be resolvable."""
        import ast

        test_files = _get_test_files()
        conftest = TEST_ROOT / "conftest.py"
        if conftest.exists():
            test_files.append(conftest)

        all_fixtures = set()
        for test_file in test_files:
            all_fixtures.update(_get_fixture_names(test_file))

        # Add built-in fixtures
        all_fixtures.update(REQUIRED_FIXTURES)

        for test_file in test_files:
            try:
                tree = ast.parse(test_file.read_text(encoding="utf-8"))
                for node in ast.walk(tree):
                    if isinstance(node, ast.FunctionDef):
                        # Check function parameters
                        for arg in node.args.args:
                            if arg.arg in all_fixtures:
                                continue
                            # Check if it's a fixture from another module
                            if arg.arg.startswith("fixture_"):
                                assert arg.arg in all_fixtures, (
                                    f"Undefined fixture '{arg.arg}' in {test_file.name}"
                                )
            except SyntaxError:
                continue

    def test_fixture_teardown_implemented(self):
        """Fixtures with yield must have proper teardown."""
        test_files = _get_test_files()
        conftest = TEST_ROOT / "conftest.py"
        if conftest.exists():
            test_files.append(conftest)

        for test_file in test_files:
            content = test_file.read_text(encoding="utf-8")
            if "@pytest.fixture" in content:
                # Check for yield-based fixtures
                lines = content.splitlines()
                for i, line in enumerate(lines):
                    if "@pytest.fixture" in line:
                        # Look ahead for yield
                        for j in range(i + 1, min(i + 10, len(lines))):
                            if "yield" in lines[j]:
                                break
                        else:
                            # No yield found, check if it's a simple return fixture
                            pass


