class TestPerformanceBenchmarks:
    """Validate test suite performance."""

    def test_collection_time_within_bounds(self):
        """Test collection must complete within time bounds."""
        import subprocess

        start_time = time.time()
        result = subprocess.run(
            [sys.executable, "-m", "pytest", "--collect-only", "-q", str(TEST_ROOT)],
            capture_output=True,
            text=True,
            timeout=MAX_COLLECTION_TIME_SECONDS + 5
        )
        collection_time = time.time() - start_time

        assert collection_time < MAX_COLLECTION_TIME_SECONDS, (
            f"Collection took {collection_time:.2f}s, exceeding {MAX_COLLECTION_TIME_SECONDS}s limit"
        )
        assert result.returncode == 0, f"Collection failed: {result.stderr}"

    def test_execution_time_within_bounds(self):
        """Full test suite must complete within time bounds."""
        import subprocess

        start_time = time.time()
        result = subprocess.run(
            [sys.executable, "-m", "pytest", "-q", "--tb=no", str(TEST_ROOT)],
            capture_output=True,
            text=True,
            timeout=MAX_EXECUTION_TIME_SECONDS + 10
        )
        execution_time = time.time() - start_time

        assert execution_time < MAX_EXECUTION_TIME_SECONDS, (
            f"Execution took {execution_time:.2f}s, exceeding {MAX_EXECUTION_TIME_SECONDS}s limit"
        )

