class TestCrossModuleDependencies:
    """Validate cross-module dependencies."""

    def test_no_circular_imports(self):
        """Test modules must not have circular imports."""
        test_files = _get_test_files()
        sys.path.insert(0, str(TEST_ROOT))

        try:
            for test_file in test_files:
                module_name = test_file.stem
                try:
                    importlib.import_module(module_name)
                except ImportError as e:
                    if "circular" in str(e).lower():
                        pytest.fail(f"Circular import in {module_name}: {e}")
        finally:
            sys.path.remove(str(TEST_ROOT))

    def test_shared_fixtures_accessible(self):
        """Fixtures from conftest must be accessible in all test modules."""
        conftest = TEST_ROOT / "conftest.py"
        if not conftest.exists():
            conftest = PROJECT_ROOT / "conftest.py"

        if conftest.exists():
            conftest_fixtures = set(_get_fixture_names(conftest))
            test_files = _get_test_files()

            for test_file in test_files:
                content = test_file.read_text(encoding="utf-8")
                # Check if any conftest fixture is used
                for fixture in conftest_fixtures:
                    if fixture in content:
                        # Verify it's used as a parameter
                        assert f"({fixture}" in content or f", {fixture}" in content, (
                            f"Fixture {fixture} referenced but not used in {test_file.name}"
                        )

    def test_test_modules_do_not_import_each_other(self):
        """Test modules should not import each other (isolated)."""
        test_files = _get_test_files()
        test_module_names = {f.stem for f in test_files}

        for test_file in test_files:
            content = test_file.read_text(encoding="utf-8")
            for module_name in test_module_names:
                if module_name != test_file.stem:
                    assert f"import {module_name}" not in content, (
                        f"{test_file.name} imports {module_name}"
                    )
                    assert f"from {module_name}" not in content, (
                        f"{test_file.name} imports from {module_name}"
                    )


